import {esc,CHANNELS} from './clarity.js';
import {MEETING_TYPES,MEETING_TIMES} from './meeting-options.js';
import {normalizeEntry,validEntries,updateEntry,deleteEntry,entryWarning} from './meeting-store.js';
const labels={date:'Date',name:'Meeting name',attendance:'Attendance',type:'Meeting type',time:'Meeting time',new_members:'New members',returning_members:'Returning members',days_promoted_before:'Promotion started days before',reach:'Instagram reach before meeting',signups:'Signups before meeting',special_event:'Special event',notes:'Notes'};
function control(r,k){const id=`entry-${r.id}-${k}`,label=labels[k],value=r[k]??'';let field;
 if(['type','time','special_event'].includes(k)){const values=k==='type'?MEETING_TYPES:k==='time'?MEETING_TIMES:['Yes','No'];const current=k==='special_event'?(value===true?'Yes':value===false?'No':value):value;const options=[...new Set([...values,...(current?[current]:[])])];field=`<select id="${esc(id)}" data-field="${k}"><option value="">Not provided</option>${options.map(v=>`<option${v===current?' selected':''}>${esc(v)}</option>`).join('')}</select>`}
 else if(k==='notes')field=`<textarea id="${esc(id)}" data-field="${k}" maxlength="1000" placeholder="Context without personal student information">${esc(value)}</textarea>`;
 else field=`<input id="${esc(id)}" data-field="${k}" type="${k==='date'?'date':k==='name'?'text':'number'}" value="${esc(value)}" ${['date','attendance'].includes(k)?'required':''} ${!['date','name'].includes(k)?'min="0" step="1" max="'+(k==='reach'?10000000:100000)+'"':'maxlength="150"'}>`;
 return `<label for="${esc(id)}"><span>${label}${['date','attendance'].includes(k)?' *':''}</span>${field}</label>`;
}
function promotion(r){const selected=(r.promotion||'').split(' + ').filter(Boolean).map(x=>x==='Announcements'?'Classroom Announcement':x);const options=[...new Set([...CHANNELS,...selected])];return `<details class="entry-promotion"><summary>Promotion <span class="channel-summary">${selected.length?selected.map(esc).join(' · '):'Optional'}</span></summary><div class="channel-options">${options.map(v=>`<label><input type="checkbox" data-channel="${esc(v)}" ${selected.includes(v)?'checked':''}>${esc(v)}</label>`).join('')}</div></details>`}
function rowHTML(r){return `<tbody data-entry="${esc(r.id)}"><tr class="editor-main-row">${['date','name','attendance','type'].map(k=>`<td>${control(r,k)}</td>`).join('')}<td>${promotion(r)}</td></tr><tr class="editor-detail-row"><td colspan="5"><details class="entry-extra"><summary>More details</summary><div class="editor-extra-grid">${['new_members','returning_members','time','days_promoted_before','reach','signups','special_event','notes'].map(k=>control(r,k)).join('')}</div>${r.members?.length?'<p class="footnote">This record includes anonymous attendance IDs from your file. If attendance changes, update the source file or clear these IDs.</p><button type="button" class="text-link" data-clear-ids>Clear imported attendance IDs</button>':''}</details><details class="entry-row-menu"><summary aria-label="Meeting actions">•••</summary><button type="button" class="text-link" data-delete>Delete meeting</button></details><p class="entry-error error" role="status"></p><p class="entry-warning" role="status"></p></td></tr></tbody>`}
export function mountMeetingEditor(root,{records,onChange,save,initialError}){
 let data=records.map(r=>({...r})),undo=null;
 const notify=()=>{const error=save(data);onChange(validEntries(data));root.querySelector('#entry-save-status').textContent=error||'✓ Changes saved';root.querySelector('#entry-save-status').classList.toggle('error',!!error);updateStatus();};
 function updateStatus(){let invalid=false;for(const r of data){const group=[...root.querySelectorAll('[data-entry]')].find(g=>g.dataset.entry===r.id);let error='';try{normalizeEntry(r)}catch(e){error=e.message}if(error)invalid=true;if(group){group.querySelector('.entry-error').textContent=error;group.querySelector('.entry-warning').textContent=entryWarning(r);group.querySelectorAll('[data-field]').forEach(el=>el.setAttribute('aria-describedby',`error-${r.id}`));group.querySelector('.entry-error').id=`error-${r.id}`;}}const button=root.querySelector('#analyze-entered');if(button)button.disabled=!data.length||invalid;const count=root.querySelector('#entry-count');if(count)count.textContent=`${data.length} meeting${data.length===1?'':'s'}`;}
 function draw(){root.innerHTML=`<div class="page-heading"><div><p class="eyebrow">Your Data</p><h1>${data.length?'Your meeting history':'Add your first meeting'}</h1><p>Add or update meetings anytime. <strong>Only Date and Attendance are required.</strong> Add more details for deeper insights.</p></div></div><div class="editor-status"><span id="entry-count"></span><span id="entry-save-status" role="status">${esc(initialError||(data.length?'Saved on this device':'Ready for your first meeting'))}</span></div>${data.length?`<div class="editor-toolbar"><button class="button" id="add-editor-row">+ Add meeting</button><a class="text-link" href="#import">Import spreadsheet →</a></div><table class="meeting-editor"><caption class="sr-only">Editable meeting history</caption><thead><tr>${['Date','Meeting name','Attendance','Meeting type','Promotion'].map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead>${data.map(rowHTML).join('')}</table><div class="editor-actions"><span class="footnote">Update your history after every meeting.</span><button class="button primary" id="analyze-entered">See My Insights →</button></div>`:`<form id="first-meeting" class="first-meeting"><div class="form-grid">${['date','attendance','name','type'].map(k=>control({id:'first'},k)).join('')}</div><p id="first-error" class="error" role="alert"></p><button class="button primary">Add Meeting</button></form>`}<p id="delete-status" role="status">${undo?'Meeting deleted. <button id="undo-delete" class="text-link">Undo</button>':''}</p><p class="footnote">Your meetings stay in this browser on this device. No account or cloud sync. Avoid personal student information.</p><a class="text-link" href="#import">Upload a spreadsheet or use a template →</a>`;
 root.querySelector('#first-meeting')?.addEventListener('submit',e=>{e.preventDefault();const raw={id:crypto.randomUUID()};e.target.querySelectorAll('[data-field]').forEach(el=>raw[el.dataset.field]=el.value);try{data.push(normalizeEntry(raw));draw();notify()}catch(err){root.querySelector('#first-error').textContent=err.message}});
 root.querySelector('#add-editor-row')?.addEventListener('click',()=>{if(data.length>=2000){root.querySelector('#entry-save-status').textContent='This workspace supports up to 2,000 meetings.';return}const row={id:crypto.randomUUID(),date:'',attendance:'',name:''};data.push(row);draw();notify();root.querySelector(`[id="entry-${row.id}-date"]`).focus()});
 root.querySelector('#analyze-entered')?.addEventListener('click',()=>{notify();if(!root.querySelector('#analyze-entered').disabled)location.hash='overview'});
 root.querySelector('#undo-delete')?.addEventListener('click',()=>{data.splice(undo.index,0,undo.record);undo=null;draw();notify()});
 for(const group of root.querySelectorAll('[data-entry]')){group.addEventListener('input',e=>{const el=e.target;if(!el.matches('[data-field],[data-channel]'))return;const patch=el.dataset.field?{[el.dataset.field]:el.value}:{promotion:[...group.querySelectorAll('[data-channel]:checked')].map(c=>c.dataset.channel).join(' + ')};data=updateEntry(data,group.dataset.entry,patch);if('promotion'in patch)group.querySelector('.channel-summary').textContent=patch.promotion||'Optional';notify()});group.querySelector('[data-clear-ids]')?.addEventListener('click',()=>{data=updateEntry(data,group.dataset.entry,{members:null});draw();notify()});group.querySelector('[data-delete]').onclick=()=>{const index=data.findIndex(r=>r.id===group.dataset.entry);undo={record:data[index],index};data=deleteEntry(data,group.dataset.entry);draw();notify()};}
 updateStatus();
 }
 draw();
}
